-- =====================================================================
-- V1__init_schema.sql
-- Chốt database theo: Database_Design_Domestic_Flight_Booking_v0 (đã duyệt)
-- Nền tảng: PostgreSQL (Aiven)
--
-- Quyết định khi triển khai (đã chốt):
--   * ENUM của v0 thể hiện bằng VARCHAR + CHECK  (đúng v0: "ENUM là nhóm giá trị
--     nghiệp vụ dự kiến, cần chốt lại khi triển khai")
--   * Khóa chính: BIGINT GENERATED BY DEFAULT AS IDENTITY (cho phép seed id cố định)
--   * Cột thời gian: TIMESTAMPTZ (quy đổi theo múi giờ, chuẩn lưu UTC)
--   * Bổ sung UNIQUE / INDEX / CHECK hợp lý theo section F (bước 3 "chốt
--     PK/FK/UNIQUE/INDEX/CHECK") — mỗi chỗ đều có comment lý do
-- =====================================================================

-- ========== 1. AUTHENTICATION & RBAC ==========

CREATE TABLE users (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email         VARCHAR(255) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    full_name     VARCHAR(150) NOT NULL,
    phone         VARCHAR(20),
    avatar_url    TEXT,
    status        VARCHAR(20)  NOT NULL DEFAULT 'ACTIVE'
                  CHECK (status IN ('ACTIVE', 'INACTIVE')),
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE roles (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(50) NOT NULL UNIQUE,
    description VARCHAR(255)
);

CREATE TABLE permissions (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    permission_key VARCHAR(100) NOT NULL UNIQUE,
    description    VARCHAR(255)
);

CREATE TABLE user_roles (
    user_id BIGINT NOT NULL REFERENCES users (id),
    role_id BIGINT NOT NULL REFERENCES roles (id),
    PRIMARY KEY (user_id, role_id)
);

CREATE TABLE role_permissions (
    role_id       BIGINT NOT NULL REFERENCES roles (id),
    permission_id BIGINT NOT NULL REFERENCES permissions (id),
    PRIMARY KEY (role_id, permission_id)
);

-- ========== 2. MASTER DATA ==========

CREATE TABLE airlines (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    airline_code VARCHAR(10)  NOT NULL UNIQUE,
    airline_name VARCHAR(150) NOT NULL,
    country      VARCHAR(100),
    logo_url     VARCHAR(500),
    status       VARCHAR(20)  NOT NULL DEFAULT 'ACTIVE'
                 CHECK (status IN ('ACTIVE', 'INACTIVE'))
);

CREATE TABLE cities (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    city_code VARCHAR(10)  NOT NULL UNIQUE,
    city_name VARCHAR(100) NOT NULL,
    country   VARCHAR(100) NOT NULL
);

CREATE TABLE airports (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    airport_code VARCHAR(10)   NOT NULL UNIQUE,
    airport_name VARCHAR(150)  NOT NULL,
    city_id      BIGINT        NOT NULL REFERENCES cities (id),
    latitude     NUMERIC(9, 6),
    longitude    NUMERIC(9, 6)
);
-- FK được query thường xuyên (airport theo thành phố khi tìm chuyến bay)
CREATE INDEX idx_airports_city_id ON airports (city_id);

CREATE TABLE aircrafts (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    aircraft_code VARCHAR(30) NOT NULL UNIQUE,
    model         VARCHAR(100) NOT NULL,
    manufacturer  VARCHAR(100),
    seat_capacity INTEGER      NOT NULL CHECK (seat_capacity > 0)
);

CREATE TABLE seat_types (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    type_code VARCHAR(30) NOT NULL UNIQUE,
    type_name VARCHAR(100) NOT NULL,
    seat_class VARCHAR(20) NOT NULL
               CHECK (seat_class IN ('ECONOMY', 'BUSINESS', 'FIRST'))
);

CREATE TABLE seat_configurations (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    aircraft_id  BIGINT      NOT NULL REFERENCES aircrafts (id),
    seat_type_id BIGINT      NOT NULL REFERENCES seat_types (id),
    row_number   INTEGER     NOT NULL,
    column_code  VARCHAR(5)  NOT NULL,
    -- một vị trí trên một máy bay chỉ tồn tại một cấu hình ghế
    UNIQUE (aircraft_id, row_number, column_code)
);

-- ========== 3. CONTENT & KHUYẾN MÃI ==========

CREATE TABLE promotions (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    promo_code    VARCHAR(50)   NOT NULL UNIQUE,
    promo_name    VARCHAR(150)  NOT NULL,
    discount_type VARCHAR(20)   NOT NULL CHECK (discount_type IN ('PERCENT', 'AMOUNT')),
    discount_value NUMERIC(12, 2) NOT NULL CHECK (discount_value >= 0),
    start_date    DATE          NOT NULL,
    end_date      DATE          NOT NULL,
    status        VARCHAR(20)   NOT NULL DEFAULT 'ACTIVE'
                  CHECK (status IN ('ACTIVE', 'INACTIVE', 'EXPIRED')),
    CHECK (end_date >= start_date)
);

CREATE TABLE vouchers (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    voucher_code   VARCHAR(50)   NOT NULL UNIQUE,
    voucher_type   VARCHAR(20)   NOT NULL CHECK (voucher_type IN ('PERCENT', 'AMOUNT')),
    value_amount   NUMERIC(12, 2) NOT NULL CHECK (value_amount >= 0),
    start_date     DATE          NOT NULL,
    end_date       DATE          NOT NULL,
    usage_limit    INTEGER       CHECK (usage_limit IS NULL OR usage_limit > 0),
    per_user_limit INTEGER       CHECK (per_user_limit IS NULL OR per_user_limit > 0),
    scope          VARCHAR(20)   NOT NULL CHECK (scope IN ('GLOBAL', 'ASSIGNED')),
    status         VARCHAR(20)   NOT NULL DEFAULT 'ACTIVE'
                   CHECK (status IN ('ACTIVE', 'INACTIVE', 'EXPIRED')),
    CHECK (end_date >= start_date)
);

CREATE TABLE user_vouchers (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users (id),
    voucher_id  BIGINT NOT NULL REFERENCES vouchers (id),
    status      VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE'
                CHECK (status IN ('AVAILABLE', 'USED', 'EXPIRED')),
    assigned_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    used_at     TIMESTAMPTZ,
    -- một người dùng chỉ được cấp một voucher loại ASSIGNED tối đa một lần
    UNIQUE (user_id, voucher_id)
);

CREATE TABLE news_categories (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(100) NOT NULL UNIQUE,
    description VARCHAR(255),
    status      VARCHAR(20)  NOT NULL DEFAULT 'ACTIVE'
                CHECK (status IN ('ACTIVE', 'INACTIVE')),
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE news_items (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title        VARCHAR(255) NOT NULL,
    content      TEXT         NOT NULL,
    published_at TIMESTAMPTZ,
    status       VARCHAR(20)  NOT NULL DEFAULT 'DRAFT'
                 CHECK (status IN ('DRAFT', 'PUBLISHED'))
);

CREATE TABLE news_category_mapping (
    news_id     BIGINT NOT NULL REFERENCES news_items (id),
    category_id BIGINT NOT NULL REFERENCES news_categories (id),
    PRIMARY KEY (news_id, category_id)
);

-- ========== 4. FLIGHT & FARE ==========

CREATE TABLE flights (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    flight_number         VARCHAR(20) NOT NULL,
    airline_id            BIGINT      NOT NULL REFERENCES airlines (id),
    aircraft_id           BIGINT      NOT NULL REFERENCES aircrafts (id),
    departure_airport_id  BIGINT      NOT NULL REFERENCES airports (id),
    arrival_airport_id    BIGINT      NOT NULL REFERENCES airports (id),
    scheduled_departure   TIMESTAMPTZ NOT NULL,
    scheduled_arrival     TIMESTAMPTZ NOT NULL,
    status                VARCHAR(20) NOT NULL DEFAULT 'SCHEDULED'
                          CHECK (status IN ('SCHEDULED', 'DELAYED', 'CANCELLED', 'COMPLETED')),
    sale_open             BOOLEAN     NOT NULL DEFAULT TRUE,
    -- ràng buộc nghiệp vụ (v0 section E): điểm đi ≠ điểm đến
    CHECK (departure_airport_id <> arrival_airport_id),
    CHECK (scheduled_arrival > scheduled_departure)
);
-- index phục vụ Flight Search: (đi, đến, ngày khởi hành)
CREATE INDEX idx_flights_route_departure ON flights (departure_airport_id, arrival_airport_id, scheduled_departure);
CREATE INDEX idx_flights_airline_id ON flights (airline_id);
CREATE INDEX idx_flights_aircraft_id ON flights (aircraft_id);

CREATE TABLE fare_classes (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    class_code VARCHAR(30) NOT NULL UNIQUE,
    class_name VARCHAR(100) NOT NULL,
    seat_class VARCHAR(20)  NOT NULL
               CHECK (seat_class IN ('ECONOMY', 'BUSINESS', 'FIRST'))
);

CREATE TABLE flight_fares (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    flight_id      BIGINT       NOT NULL REFERENCES flights (id),
    fare_class_id  BIGINT       NOT NULL REFERENCES fare_classes (id),
    price          NUMERIC(12, 2) NOT NULL CHECK (price >= 0),
    currency       VARCHAR(3)   NOT NULL DEFAULT 'VND',
    effective_date TIMESTAMPTZ  NOT NULL DEFAULT now(),
    status         VARCHAR(20)  NOT NULL DEFAULT 'ACTIVE'
                   CHECK (status IN ('ACTIVE', 'INACTIVE')),
    -- một hạng vé cho một chuyến bay chỉ có một giá hiệu lực cho một thời điểm
    UNIQUE (flight_id, fare_class_id, effective_date)
);

CREATE TABLE flight_seats (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    flight_id      BIGINT       NOT NULL REFERENCES flights (id),
    seat_config_id BIGINT       NOT NULL REFERENCES seat_configurations (id),
    seat_code      VARCHAR(10)  NOT NULL,
    status         VARCHAR(20)  NOT NULL DEFAULT 'AVAILABLE'
                   CHECK (status IN ('AVAILABLE', 'HOLD', 'BOOKED', 'UNAVAILABLE')),
    price_at_time  NUMERIC(12, 2) CHECK (price_at_time IS NULL OR price_at_time >= 0),
    -- ghế xác định duy nhất trong một chuyến bay
    UNIQUE (flight_id, seat_code)
);

CREATE TABLE baggage_options (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name      VARCHAR(100) NOT NULL,
    weight_kg NUMERIC(6, 2) NOT NULL CHECK (weight_kg > 0),
    price     NUMERIC(12, 2) NOT NULL CHECK (price >= 0),
    status    VARCHAR(20) NOT NULL DEFAULT 'ACTIVE'
              CHECK (status IN ('ACTIVE', 'INACTIVE'))
);

-- ========== 5. BOOKING CORE ==========

CREATE TABLE bookings (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_code      VARCHAR(30)   NOT NULL UNIQUE,
    user_id           BIGINT        NOT NULL REFERENCES users (id),
    trip_type         VARCHAR(20)   NOT NULL CHECK (trip_type IN ('ONE_WAY', 'ROUND_TRIP')),
    status            VARCHAR(20)   NOT NULL DEFAULT 'PENDING_PAYMENT'
                      CHECK (status IN ('PENDING_PAYMENT', 'CONFIRMED', 'CANCELLED', 'EXPIRED')),
    total_amount      NUMERIC(12, 2) NOT NULL CHECK (total_amount >= 0),
    snapshot_currency VARCHAR(3)    NOT NULL DEFAULT 'VND',
    created_at        TIMESTAMPTZ   NOT NULL DEFAULT now()
);
CREATE INDEX idx_bookings_user_id ON bookings (user_id);

CREATE TABLE booking_flights (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_id     BIGINT       NOT NULL REFERENCES bookings (id),
    flight_id      BIGINT       NOT NULL REFERENCES flights (id),
    segment_order  INTEGER      NOT NULL,
    fare_class_id  BIGINT       NOT NULL REFERENCES fare_classes (id),
    price_snapshot NUMERIC(12, 2) NOT NULL CHECK (price_snapshot >= 0),
    currency       VARCHAR(3)   NOT NULL DEFAULT 'VND',
    -- thứ tự chặng của một booking không được trùng (v0 section E)
    UNIQUE (booking_id, segment_order)
);
CREATE INDEX idx_booking_flights_flight_id ON booking_flights (flight_id);

CREATE TABLE passengers (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_id     BIGINT      NOT NULL REFERENCES bookings (id),
    full_name      VARCHAR(150) NOT NULL,
    gender         VARCHAR(20) NOT NULL CHECK (gender IN ('MALE', 'FEMALE', 'OTHER')),
    birth_date     DATE        NOT NULL,
    passenger_type VARCHAR(20) NOT NULL CHECK (passenger_type IN ('ADULT', 'CHILD', 'INFANT')),
    passport_number VARCHAR(50),
    phone          VARCHAR(20),
    email          VARCHAR(255)
);
CREATE INDEX idx_passengers_booking_id ON passengers (booking_id);

CREATE TABLE seat_holds (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_id     BIGINT      NOT NULL REFERENCES bookings (id),
    flight_seat_id BIGINT      NOT NULL REFERENCES flight_seats (id),
    held_until     TIMESTAMPTZ NOT NULL,
    status         VARCHAR(20) NOT NULL DEFAULT 'HOLD'
                   CHECK (status IN ('HOLD', 'CONFIRMED', 'RELEASED'))
);
CREATE INDEX idx_seat_holds_booking_id ON seat_holds (booking_id);
-- v0 section E: không được có hai Hold hợp lệ đồng thời cho cùng một ghế.
-- Ràng buộc này do tầng service chốt khi hết hạn giữ chỗ (RELEASED), DB ngăn
-- trường hợp 2 dòng HOLD cùng lúc — ngay cả khi dữ liệu cũ chưa được release.
CREATE UNIQUE INDEX uq_seat_holds_active_per_seat ON seat_holds (flight_seat_id) WHERE status = 'HOLD';

CREATE TABLE booking_baggages (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_id         BIGINT       NOT NULL REFERENCES bookings (id),
    passenger_id       BIGINT       NOT NULL REFERENCES passengers (id),
    baggage_option_id  BIGINT       NOT NULL REFERENCES baggage_options (id),
    quantity           INTEGER      NOT NULL DEFAULT 1 CHECK (quantity > 0),
    price_snapshot     NUMERIC(12, 2) NOT NULL CHECK (price_snapshot >= 0),
    currency           VARCHAR(3)   NOT NULL DEFAULT 'VND'
);
CREATE INDEX idx_booking_baggages_booking_id ON booking_baggages (booking_id);
CREATE INDEX idx_booking_baggages_passenger_id ON booking_baggages (passenger_id);
-- v0 section E: hành khách khai trong booking_baggages phải thuộc cùng booking
-- (buộc qua FK kép — tại tầng service)

CREATE TABLE voucher_usages (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    voucher_id      BIGINT       NOT NULL REFERENCES vouchers (id),
    user_id         BIGINT       NOT NULL REFERENCES users (id),
    booking_id      BIGINT       NOT NULL REFERENCES bookings (id),
    discount_amount NUMERIC(12, 2) NOT NULL CHECK (discount_amount >= 0),
    used_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    -- v0 section B: bookings → voucher_usages là 1–0..1 (một booking dùng tối đa 1 voucher)
    UNIQUE (booking_id)
);
CREATE INDEX idx_voucher_usages_voucher_id ON voucher_usages (voucher_id);
CREATE INDEX idx_voucher_usages_user_id ON voucher_usages (user_id);

CREATE TABLE payments (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_id     BIGINT       NOT NULL REFERENCES bookings (id),
    amount         NUMERIC(12, 2) NOT NULL CHECK (amount >= 0),
    currency       VARCHAR(3)   NOT NULL DEFAULT 'VND',
    payment_method VARCHAR(50)  NOT NULL,
    provider       VARCHAR(50),
    gateway_ref    VARCHAR(150),
    status         VARCHAR(20)  NOT NULL DEFAULT 'PENDING'
                   CHECK (status IN ('PENDING', 'SUCCESS', 'FAILED')),
    retry_count    INTEGER      NOT NULL DEFAULT 0 CHECK (retry_count >= 0),
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    paid_at        TIMESTAMPTZ
);
-- v0 section B: 1 booking → N payments (cho phép thanh toán lại / retry)
CREATE INDEX idx_payments_booking_id ON payments (booking_id);

CREATE TABLE e_tickets (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_id        BIGINT NOT NULL REFERENCES bookings (id),
    booking_flight_id BIGINT NOT NULL REFERENCES booking_flights (id),
    passenger_id      BIGINT NOT NULL REFERENCES passengers (id),
    flight_seat_id    BIGINT REFERENCES flight_seats (id),
    pnr_code          VARCHAR(20) NOT NULL UNIQUE,
    ticket_code       VARCHAR(30) NOT NULL UNIQUE,
    issued_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_e_tickets_booking_id ON e_tickets (booking_id);
CREATE INDEX idx_e_tickets_booking_flight_id ON e_tickets (booking_flight_id);
CREATE INDEX idx_e_tickets_passenger_id ON e_tickets (passenger_id);
-- v0 section E: E-Ticket chỉ phát hành sau Payment SUCCESS — ràng buộc tại tầng service